// Участок 45, линия B. Два дня в винзенском пункте Красного Креста: грипп в спортзале, сорок коек за занавеской, одна сестра —
// Вибке. Утром — сестринская комната школы (кактус «Bitte nicht gießen!» на подоконнике — ключ от шкафа под горшком), колонна
// и листок Мерле / доктор Кесслер / работа с января. За обедом Вибке рассказывает про водителей: Нильс с октября один, в сочельник
// спит в кабине. Днём — запертый шкаф школьной медсестры (находка B), аптека в старом городе с Хауке (подсобка, мёртвый за
// дверью). Вечер и ночь: звёзды из бумаги, фрау Энгель, судороги у ребёнка. Четверг: утро после ночи, доска поиска, Вибке и
// посылка для хутора, рынок у школы, автобус, хутор к 16:30.
const X = (scene: Omit<Scene, 'for' | 'chapter'>): Scene => S45({ ...scene, for: 'any', chapter: 'ch3' });
const W = (scene: Omit<Scene, 'for' | 'chapter' | 'location'>): Scene => X({ ...scene, location: winsen45, camp: scene.camp ?? trip45(winsen45), safe: scene.safe ?? true });
const N = (scene: Omit<Scene, 'for' | 'chapter' | 'location'>): Scene => W({ ...scene, camp: trip45(winsen45, 'sleep') });
const toWinsen: Effect = { move: winsen45 };
const toJest: Effect = { move: jest45 };
const toFarm: Effect = { move: farm45 };
const bruise: Effect[] = [{ injure: 'bruise', site: 'leftLeg', severity: 2 }, { body: 'stress', delta: 4 }];
const room = { tempC: 17, outdoor: false, wet: false };
const notMerle: Cond = not(merle45);
const ninaSchool: Cond = all(ninaFarm, any(v('w.c42_school', 'go'), v('w.c42_school', 'herself')));
const keyCab: Cond = own45('cab', 'key');
const barCab: Cond = own45('cab', 'bar');
/** Есть чем сбить жар: детское из шкафа или аптечное с Хауке. */
const hasSyrup: Cond = any({ has: 'c45_kids_meds' }, flag('w.c45_pharm_meds'));
const engelSat: Cond = any(own45('be', 'engel'), own45('bn', 'engel'));
const found = (how: 'key' | 'bar'): Effect[] => [set45('cab', how), w45('cabinet', how)];

